use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_bytes: Vec<u8> = serde_json::from_str(&input).unwrap();
    let mut result = String::new();
    for byte in input_bytes {
        let hex = format!("{:02x}", byte);
        result.push_str(hex);
    }
    result
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[0,15,255]}");
    let output = solve(input);
    println!("{}", serde_json::to_string(&output));
}
```

